"use strict";App.Pages.InPersonConfirmation=function(){function showMessage(message,type){$message.removeClass("d-none alert-success alert-warning alert-danger").addClass("alert-"+type).text(message)}var $message=$("#local-printing-message"),$reprintButton=$("#reprint-walkin-ticket");return document.addEventListener("DOMContentLoaded",function(){var ticket=vars("walkin_ticket");if(!ticket||!ticket.queue_number||!App.Utils.LocalPrinting.isEnabled())return void $reprintButton.addClass("d-none");var failedHash=window.sessionStorage.getItem("easyappointments_local_print_failed");failedHash===ticket.appointment_hash&&showMessage(lang("local_printing_failed"),"warning"),$reprintButton.on("click",function(){$reprintButton.prop("disabled",!0),App.Utils.LocalPrinting.print(ticket).then(function(){window.sessionStorage.removeItem("easyappointments_local_print_failed"),showMessage(lang("local_printing_success"),"success")})["catch"](function(error){window.sessionStorage.setItem("easyappointments_local_print_failed",ticket.appointment_hash),showMessage(lang("local_printing_failed")+" "+error.message,"warning")})["finally"](function(){$reprintButton.prop("disabled",!1)})})}),{}}();